"""Generate Solidity/Noir admission-tree constants from the pinned Barretenberg parameters."""
from pathlib import Path
import poseidon2 as p2
from chain_registry import DEPTH, LEAF_TAG, ZEROS

ROOT = Path(__file__).resolve().parents[1]
full_half = p2._RF // 2
constants = [value for i, row in enumerate(p2._RC)
             for value in (row if i < full_half or i >= full_half + p2._RP else row[:1])]
lines = ['// SPDX-License-Identifier: MIT', 'pragma solidity 0.8.28;', '',
         '// Generated by prover/generate_registry_config.py; do not edit.',
         f'uint256 constant CHAIN_REGISTRY_DEPTH = {DEPTH};',
         f'uint256 constant CHAIN_REGISTRY_CAPACITY = {1 << DEPTH};',
         f'uint256 constant CHAIN_REGISTRY_LEAF_TAG = {LEAF_TAG};',
         f'uint256 constant CHAIN_REGISTRY_EMPTY_ROOT = {ZEROS[-1]};',
         f'uint256 constant REGISTRY_FIELD = {p2.P};',
         f'uint256 constant REGISTRY_LENGTH_TAG = {p2.TWO_POW_64};',
         f'uint256 constant REGISTRY_HALF_FULL_ROUNDS = {full_half};',
         f'uint256 constant REGISTRY_PARTIAL_ROUNDS = {p2._RP};',
         f'uint256 constant REGISTRY_TOTAL_ROUNDS = {p2._RF + p2._RP};',
         f'uint256 constant REGISTRY_ROUND_CONSTANTS = {len(constants)};', '']
for i, diagonal in enumerate(p2._DIAG):
    lines.append(f'uint256 constant REGISTRY_DIAGONAL_{i} = {diagonal};')
for name, values in [('registryRoundConstants', constants), ('registryZeros', ZEROS)]:
    lines += ['', f'function {name}() pure returns (uint256[{len(values)}] memory) {{',
              '    return [', '        uint256(' + str(values[0]) + '),',
              *['        ' + str(value) + (',' if i < len(values) - 1 else '') for i, value in enumerate(values[1:], 1)],
              '    ];', '}']
(ROOT / 'contracts/src/ChainRegistryConfig.sol').write_text('\n'.join(lines) + '\n')
(ROOT / 'circuits/zkip_lite/src/chain_registry_constants.nr').write_text(
    '// Generated by prover/generate_registry_config.py; do not edit.\n'
    f'pub global CHAIN_REGISTRY_DEPTH: u32 = {DEPTH};\n'
    f'pub global CHAIN_REGISTRY_LEAF_TAG: Field = {LEAF_TAG};\n')
